//! SmartTyping against the shared oracle. Port of md.win `SmartTypingTests`.
//!
//! `fixtures/typing-vectors.json` is the cross-port contract for `enter` and `capitalize`: 1350
//! vectors (512 enter, 838 capitalize) generated by the TypeScript reference that
//! `docs/smart-typing.md` was written against, copied verbatim into md, md.macOS, md.Android,
//! md.win and here — exactly the arrangement `plot-vectors.json` has for the plotter. Every
//! offset is a UTF-16 code unit; every unit outside U+0020–U+007E is a `\uXXXX` escape, so no
//! editor can normalise an invisible character; `expected` is the JSON literal null, never the
//! string "none".
//!
//! It is a specification, not a recording: no vector is skipped, none is "close enough", and a
//! disputed one is changed in the JSON first, in one commit across the repos. The one place md.win
//! disagrees with the prose of the spec — .NET's invariant casing pins U+0131 to itself where the
//! vector `cap-typed-dotless-i` wants `I` — is decided the vectors' way inside SmartTyping and
//! documented there.
//!
//! Two shapes over the same corpus, as in md.win: one check per vector, keyed by id, so a failing
//! case is named; and one walk per array that reports all mismatches in a single message, which is
//! what a port iterates on. Every vector runs through both entry points (`&str` and
//! `Utf16Text`). The lone-surrogate behaviour (§0.9, §2.1a) cannot be a vector — Swift's
//! JSONDecoder rejects an unpaired escape, and so does serde_json — so it is a native test here,
//! as on Kotlin and C#, through the `_utf16` entry points (a Rust `&str` cannot hold one).

mod common;

use std::collections::HashMap;
use std::sync::OnceLock;
use std::time::Instant;

use md_core::editing::smart_typing::{self, EnterEdit};
use md_core::text::utf16::Utf16Text;
use serde_json::Value;

// MARK: - The corpus

struct EnterVector {
    id: String,
    text: String,
    start: isize,
    end: isize,
    expected: Option<EnterEdit>,
}

struct CapitalizeVector {
    id: String,
    text: String,
    start: isize,
    end: isize,
    typed: String,
    expected: Option<String>,
}

struct Vectors {
    enter_count: usize,
    capitalize_count: usize,
    enter: Vec<EnterVector>,
    capitalize: Vec<CapitalizeVector>,
}

fn string(row: &Value, key: &str) -> String {
    row[key].as_str().unwrap_or_else(|| panic!("{key} is not a string in {row}")).to_owned()
}

fn offset(row: &Value, key: &str) -> isize {
    let n = row[key].as_i64().unwrap_or_else(|| panic!("{key} is not an integer in {row}"));
    isize::try_from(n).expect("offset fits")
}

fn unsigned(row: &Value, key: &str) -> usize {
    let n = row[key].as_u64().unwrap_or_else(|| panic!("{key} is not a non-negative integer in {row}"));
    usize::try_from(n).expect("offset fits")
}

/// Read once, with serde_json: the escapes decode to the exact scalars the reference emitted (a
/// surrogate-pair escape becomes one scalar, which is the same pair again in UTF-16; an unpaired
/// one would be rejected, which is why the generator refuses to write it).
fn corpus() -> &'static Vectors {
    static CORPUS: OnceLock<Vectors> = OnceLock::new();
    CORPUS.get_or_init(|| {
        let root: Value = serde_json::from_str(&common::fixture_text("typing-vectors.json")).expect("vectors parse");
        let counts = &root["_meta"]["counts"];
        let enter = root["enter"]
            .as_array()
            .expect("enter array")
            .iter()
            .map(|row| {
                let expected = &row["expected"];
                EnterVector {
                    id: string(row, "id"),
                    text: string(row, "text"),
                    start: offset(row, "start"),
                    end: offset(row, "end"),
                    expected: (!expected.is_null()).then(|| EnterEdit {
                        location: unsigned(expected, "location"),
                        length: unsigned(expected, "length"),
                        replacement: string(expected, "replacement"),
                        caret: unsigned(expected, "caret"),
                    }),
                }
            })
            .collect();
        let capitalize = root["capitalize"]
            .as_array()
            .expect("capitalize array")
            .iter()
            .map(|row| CapitalizeVector {
                id: string(row, "id"),
                text: string(row, "text"),
                start: offset(row, "start"),
                end: offset(row, "end"),
                typed: string(row, "typed"),
                expected: (!row["expected"].is_null()).then(|| string(row, "expected")),
            })
            .collect();
        Vectors {
            enter_count: unsigned(counts, "enter"),
            capitalize_count: unsigned(counts, "capitalize"),
            enter,
            capitalize,
        }
    })
}

fn enter_by_id() -> &'static HashMap<&'static str, &'static EnterVector> {
    static MAP: OnceLock<HashMap<&'static str, &'static EnterVector>> = OnceLock::new();
    MAP.get_or_init(|| corpus().enter.iter().map(|v| (v.id.as_str(), v)).collect())
}

fn capitalize_by_id() -> &'static HashMap<&'static str, &'static CapitalizeVector> {
    static MAP: OnceLock<HashMap<&'static str, &'static CapitalizeVector>> = OnceLock::new();
    MAP.get_or_init(|| corpus().capitalize.iter().map(|v| (v.id.as_str(), v)).collect())
}

// MARK: - Rendering a mismatch

/// A string with every unit outside printable ASCII written as `\uXXXX`, so a NBSP, a ZWSP or a
/// CR is visible in a failure message.
fn show(s: Option<&str>) -> String {
    let Some(s) = s else { return "null".to_owned() };
    let mut out = String::from("\"");
    for c in s.encode_utf16() {
        match c {
            0x5C => out.push_str("\\\\"),
            0x22 => out.push_str("\\\""),
            0x0A => out.push_str("\\n"),
            0x20..=0x7E => out.push(char::from(c as u8)),
            _ => out.push_str(&format!("\\u{c:04x}")),
        }
    }
    out.push('"');
    out
}

fn show_edit(e: Option<&EnterEdit>) -> String {
    match e {
        None => "null".to_owned(),
        Some(e) => format!(
            "{{location={}, length={}, replacement={}, caret={}}}",
            e.location,
            e.length,
            show(Some(&e.replacement)),
            e.caret
        ),
    }
}

/// The mismatch for one enter vector, or `None` when it matches — through both entry points.
fn check_enter(v: &EnterVector) -> Option<String> {
    let actual = smart_typing::enter(&v.text, v.start, v.end);
    let actual16 = smart_typing::enter_utf16(&Utf16Text::new(&v.text), v.start, v.end);
    if actual == v.expected && actual16 == v.expected {
        return None;
    }
    Some(format!(
        "{}: text={} [{},{})\n    expected {}\n    actual   {}\n    utf16    {}",
        v.id,
        show(Some(&v.text)),
        v.start,
        v.end,
        show_edit(v.expected.as_ref()),
        show_edit(actual.as_ref()),
        show_edit(actual16.as_ref())
    ))
}

/// The mismatch for one capitalize vector, or `None` when it matches — through both entry points.
fn check_capitalize(v: &CapitalizeVector) -> Option<String> {
    let actual = smart_typing::capitalize(&v.text, v.start, v.end, &v.typed);
    let actual16 = smart_typing::capitalize_utf16(&Utf16Text::new(&v.text), v.start, v.end, &Utf16Text::new(&v.typed));
    if actual == v.expected && actual16 == v.expected {
        return None;
    }
    Some(format!(
        "{}: text={} [{},{}) typed={}\n    expected {}\n    actual   {}\n    utf16    {}",
        v.id,
        show(Some(&v.text)),
        v.start,
        v.end,
        show(Some(&v.typed)),
        show(v.expected.as_deref()),
        show(actual.as_deref()),
        show(actual16.as_deref())
    ))
}

fn enter_at(text: &str, start: isize, end: isize) -> Option<EnterEdit> {
    smart_typing::enter(text, start, end)
}

fn edit(location: usize, length: usize, replacement: &str, caret: usize) -> Option<EnterEdit> {
    Some(EnterEdit { location, length, replacement: replacement.to_owned(), caret })
}

fn cap(text: &str, start: isize, end: isize, typed: &str) -> Option<String> {
    smart_typing::capitalize(text, start, end, typed)
}

fn len16(s: &str) -> usize {
    s.encode_utf16().count()
}

// MARK: - The oracle, whole

#[test]
fn corpus_carries_the_counts_it_declares() {
    let v = corpus();
    assert_eq!(512, v.enter_count);
    assert_eq!(838, v.capitalize_count);
    assert_eq!(v.enter_count, v.enter.len());
    assert_eq!(v.capitalize_count, v.capitalize.len());
    assert_eq!(1350, v.enter.len() + v.capitalize.len());
    // ids are unique across both arrays
    let mut ids = std::collections::HashSet::new();
    for e in &v.enter {
        assert!(ids.insert(e.id.as_str()), "duplicate id {}", e.id);
    }
    for c in &v.capitalize {
        assert!(ids.insert(c.id.as_str()), "duplicate id {}", c.id);
    }
    // every typed is exactly one scalar
    for c in &v.capitalize {
        assert_eq!(c.typed.chars().count(), 1, "{}: typed is not one scalar: {}", c.id, show(Some(&c.typed)));
    }
}

#[test]
fn every_enter_vector_matches() {
    let v = corpus();
    let failures: Vec<String> = v.enter.iter().filter_map(check_enter).collect();
    assert!(
        failures.is_empty(),
        "{} of {} enter vectors failed:\n{}",
        failures.len(),
        v.enter.len(),
        failures.join("\n")
    );
}

#[test]
fn every_capitalize_vector_matches() {
    let v = corpus();
    let failures: Vec<String> = v.capitalize.iter().filter_map(check_capitalize).collect();
    assert!(
        failures.is_empty(),
        "{} of {} capitalize vectors failed:\n{}",
        failures.len(),
        v.capitalize.len(),
        failures.join("\n")
    );
}

// MARK: - The oracle, one case per vector

/// md.win's `[Theory]` over every enter id: each vector looked up by its id and checked alone,
/// so the first failure is named in the panic.
#[test]
fn enter_vector_matches() {
    for v in &corpus().enter {
        let failure = check_enter(enter_by_id()[v.id.as_str()]);
        assert!(failure.is_none(), "{}", failure.unwrap_or_default());
    }
}

/// md.win's `[Theory]` over every capitalize id.
#[test]
fn capitalize_vector_matches() {
    for v in &corpus().capitalize {
        let failure = check_capitalize(capitalize_by_id()[v.id.as_str()]);
        assert!(failure.is_none(), "{}", failure.unwrap_or_default());
    }
}

// MARK: - Readable cases (each is also somewhere in the oracle)

#[test]
fn bullet_item_continues_with_the_same_bullet() {
    // §1.4: insert "\n- " at the caret; the caret lands after the new marker.
    assert_eq!(edit(6, 0, "\n- ", 9), enter_at("- item", 6, 6));
}

#[test]
fn ordered_item_continues_with_the_next_number() {
    assert_eq!(edit(6, 0, "\n2. ", 10), enter_at("1. one", 6, 6));
    assert_eq!(edit(7, 0, "\n2. ", 11), enter_at("01. one", 7, 7));
}

#[test]
fn empty_item_ends_the_list() {
    // §1.3b: the empty "- " line is replaced by nothing; the caret stays on that (now empty) line.
    assert_eq!(edit(7, 2, "", 7), enter_at("- item\n- ", 9, 9));
}

#[test]
fn empty_nested_item_outdents_to_its_parent() {
    // §1.3a: "- a" / "  - " with the caret at the end of the child → the child line becomes "- ".
    assert_eq!(edit(4, 4, "- ", 6), enter_at("- a\n  - ", 8, 8));
}

#[test]
fn table_row_inserts_an_empty_row_below() {
    // §1.1: a new row padded to the header's column count, caret after its "| ".
    let table = "| a | b |\n|---|---|\n| 1 | 2 |";
    let n = len16(table);
    assert_eq!(edit(n, 0, "\n|  |  |", n + 3), enter_at(table, n as isize, n as isize));
}

#[test]
fn table_header_inserts_the_row_after_the_delimiter() {
    let table = "| a | b |\n|---|---|";
    let n = len16(table);
    assert_eq!(edit(n, 0, "\n|  |  |", n + 3), enter_at(table, 9, 9));
}

#[test]
fn caret_inside_the_prefix_is_a_plain_newline() {
    assert_eq!(None, enter_at("- item", 1, 1)); // §1.2
    assert_eq!(None, enter_at("# Title", 7, 7)); // §1.5
    assert_eq!(None, enter_at("-", 1, 1)); // a bare marker is content (§0.11)
}

#[test]
fn capital_at_the_line_start() {
    assert_eq!(Some("H".to_owned()), cap("", 0, 0, "h"));
    assert_eq!(Some("J".to_owned()), cap("Notes\n", 6, 6, "j"));
    assert_eq!(Some("I".to_owned()), cap("- ", 2, 2, "i"));
    assert_eq!(Some("T".to_owned()), cap("# ", 2, 2, "t"));
}

#[test]
fn capital_after_a_sentence() {
    assert_eq!(Some("W".to_owned()), cap("Hello. ", 7, 7, "w"));
    assert_eq!(Some("Y".to_owned()), cap("Really?! ", 9, 9, "y"));
    assert_eq!(None, cap("wait... ", 8, 8, "w")); // ellipsis
    assert_eq!(None, cap("e.g. ", 5, 5, "n")); // abbreviation
    assert_eq!(None, cap("don'", 4, 4, "t")); // no whitespace before the letter
}

#[test]
fn no_capital_inside_a_fence_or_a_table_cell() {
    assert_eq!(None, cap("```\ncode. ", 10, 10, "t"));
    assert_eq!(None, cap("| name |\n|---|\n| ", 17, 17, "n"));
    assert_eq!(None, cap("$x + ", 5, 5, "t")); // inline math
    assert_eq!(None, enter_at("```\n- item", 10, 10)); // §1.0: a fence body is not a list
}

#[test]
fn typed_must_be_one_lowercase_letter_with_an_uppercase() {
    assert_eq!(None, cap("", 0, 0, "H")); // already uppercase
    assert_eq!(None, cap("", 0, 0, "1")); // a digit
    assert_eq!(None, cap("", 0, 0, "\u{00DF}")); // ß: no one-scalar uppercase
    assert_eq!(None, cap("", 0, 0, "\u{00B5}")); // MICRO SIGN, excluded by §0.7
    assert_eq!(None, cap("", 0, 0, "\u{10D0}")); // Georgian, excluded by §0.7
    assert_eq!(None, cap("", 0, 0, "ab")); // two scalars
    assert_eq!(None, cap("", 0, 0, "")); // none
    assert_eq!(Some("I".to_owned()), cap("", 0, 0, "\u{0131}")); // dotless i: the Unicode simple mapping
    assert_eq!(Some("\u{10400}".to_owned()), cap("", 0, 0, "\u{10428}")); // a non-BMP letter (Deseret)
}

// MARK: - Lone surrogates: the native test the JSON cannot carry (§4.2)

fn units(u: &[u16]) -> Utf16Text {
    Utf16Text(u.to_vec())
}

#[test]
fn a_lone_surrogate_is_never_a_letter() {
    // §2.1a: a lone half is a scalar of category Cs — not lowercase, no uppercase.
    let empty = Utf16Text::default();
    assert_eq!(None, smart_typing::capitalize_utf16(&empty, 0, 0, &units(&[0xD800])));
    assert_eq!(None, smart_typing::capitalize_utf16(&empty, 0, 0, &units(&[0xDC00])));
    // and as text it is content, never whitespace or a letter
    let text = units(&[0xD800, b'.' as u16, b' ' as u16]);
    assert_eq!(Some("T".to_owned()), smart_typing::capitalize_utf16(&text, 3, 3, &Utf16Text::new("t")));
}

#[test]
fn a_caret_between_the_halves_of_a_pair_is_refused() {
    // §0.9: "- a😀" with the caret between the high and the low half → None for both.
    let text = "- a\u{1F600}";
    assert_eq!(None, enter_at(text, 4, 4));
    assert_eq!(None, cap(text, 4, 4, "t"));
    assert_eq!(None, enter_at(text, 0, 4));
    assert_eq!(None, cap(text, 4, 5, "t"));
    // after the pair both work
    assert_eq!(edit(5, 0, "\n- ", 8), enter_at(text, 5, 5));
}

#[test]
fn an_offset_outside_the_text_or_between_cr_and_lf_is_refused() {
    assert_eq!(None, enter_at("- a", 4, 4));
    assert_eq!(None, enter_at("- a", -1, 0));
    assert_eq!(None, cap("- a", 0, 4, "t"));
    assert_eq!(None, enter_at("- a\r\n- b", 4, 4));
    assert_eq!(None, cap("- a\r\n- b", 4, 4, "t"));
}

// MARK: - Cost (informational)

/// A one-megabyte document with the caret at its end: both functions must stay in the keystroke
/// budget (§0.14: one forward pass to the caret's line, every other walk bounded by the caret's
/// run). The timings are printed, not asserted — CI machines are slower, a debug build slower
/// still, and a wall-clock bound in a unit test is the flake this family has already paid for —
/// but the results themselves are checked, so the run cannot pass by doing nothing.
#[test]
fn one_megabyte_document_stays_in_the_keystroke_budget() {
    let block = "# Section\n\nSome prose with a sentence. Another one follows here, and a `code span` too.\n\n\
                 - first item\n- second item\n  - nested item\n- [ ] task\n\n\
                 | a | b |\n|---|---|\n| 1 | 2 |\n\n\
                 ```\ncode. not capitalized\n```\n\n\
                 > quoted line. Next sentence\n> - quoted item\n\n";
    let mut builder = String::with_capacity(1_100_000);
    let mut built = 0; // UTF-16 units so far (C#'s StringBuilder.Length)
    while built < 1_048_576 {
        builder.push_str(block);
        built += len16(block);
    }
    builder.push_str("Hello. ");
    let capitalize_text = builder;
    let enter_text = capitalize_text.clone() + "\n- item";
    let enter_len = len16(&enter_text);
    let capitalize_len = len16(&capitalize_text);
    assert!(enter_len > 1_048_576, "the document is at least one megabyte");

    // one warm-up so the first-touch allocations are not what is measured
    let _ = enter_at(&enter_text, enter_len as isize, enter_len as isize);
    let _ = cap(&capitalize_text, capitalize_len as isize, capitalize_len as isize, "t");

    let started = Instant::now();
    let entered = enter_at(&enter_text, enter_len as isize, enter_len as isize);
    let enter_ms = started.elapsed().as_secs_f64() * 1000.0;
    let started = Instant::now();
    let capital = cap(&capitalize_text, capitalize_len as isize, capitalize_len as isize, "t");
    let capitalize_ms = started.elapsed().as_secs_f64() * 1000.0;

    println!(
        "SmartTyping on a {enter_len}-unit document, caret at the end: enter {enter_ms:.2} ms, capitalize \
         {capitalize_ms:.2} ms (informational; the budget is 100 ms on the development machine)"
    );

    assert_eq!(edit(enter_len, 0, "\n- ", enter_len + 3), entered);
    assert_eq!(Some("T".to_owned()), capital);
}
